INSERT INTO properties (property_id, host_id, title, description, property_type, address, city, state, zip_code, latitude, longitude, capacity, bedrooms, bathrooms, amenities, nightly_price, cleaning_fee, status, rating, review_count, created_datetime, photo_url) VALUES
  ('p_001', 'h_001', 'Willow Glen Craftsman Cottage', 'Quiet two-bedroom cottage on a tree-lined street, a short walk to Lincoln Avenue cafes. Private driveway and a full kitchen.', 'house', '1142 Lincoln Ave', 'San Jose', 'CA', '95125', 37.3049, -121.8987, 4, 2, 1, '["wifi","kitchen","parking","washer","dryer","heating","air_conditioning"]', 189, 65, 'active', 4.86, 42, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 610 DAY), '/photos/p_001.jpg'),
  ('p_002', 'h_003', 'Budget Studio near SJSU', 'Compact studio a few blocks from the university and downtown. One parking spot and a kitchenette.', 'apartment', '455 S 10th St', 'San Jose', 'CA', '95112', 37.3352, -121.8811, 2, 1, 1, '["wifi","kitchen","parking","heating"]', 139, 40, 'active', 4.6, 18, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 280 DAY), '/photos/p_002.jpg'),
  ('p_003', 'h_002', 'Rose Garden Bungalow', 'Sunny bungalow two blocks from the Municipal Rose Garden, with a dedicated desk and off-street parking.', 'house', '1389 Dana Ave', 'San Jose', 'CA', '95126', 37.3318, -121.928, 4, 2, 1, '["wifi","kitchen","parking","washer","workspace","heating"]', 225, 75, 'active', 4.72, 31, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 520 DAY), '/photos/p_003.jpg'),
  ('p_004', 'h_004', 'Japantown Loft', 'Open-plan loft above a quiet courtyard in Japantown, close to the Saturday farmers market.', 'apartment', '610 N 5th St', 'San Jose', 'CA', '95112', 37.3487, -121.8945, 2, 1, 1, '["wifi","kitchen","parking","air_conditioning","workspace"]', 159, 50, 'active', 4.42, 27, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 450 DAY), '/photos/p_004.jpg'),
  ('p_005', 'h_001', 'Santana Row Modern Condo', 'Bright condo steps from Santana Row shops, with pool access, a garage spot with EV charging, and a full kitchen.', 'condo', '377 Santana Row', 'San Jose', 'CA', '95128', 37.321, -121.948, 3, 1, 1.5, '["wifi","kitchen","parking","pool","air_conditioning","workspace","washer","dryer","ev_charger"]', 240, 80, 'active', 4.92, 64, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 700 DAY), '/photos/p_005.jpg'),
  ('p_006', 'h_005', 'Almaden Valley Family Home', 'Four-bedroom home with a pool and hot tub at the foot of the Almaden hills. Room for the whole family.', 'house', '6721 Camino Verde Dr', 'San Jose', 'CA', '95120', 37.224, -121.873, 8, 4, 3, '["wifi","kitchen","parking","pool","hot_tub","washer","dryer","air_conditioning","heating"]', 310, 120, 'active', 4.95, 23, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 390 DAY), '/photos/p_006.jpg'),
  ('p_007', 'h_002', 'Downtown High-Rise Apartment', 'Twentieth-floor apartment with skyline views, walking distance to the convention center. Street parking only.', 'apartment', '88 E San Fernando St', 'San Jose', 'CA', '95113', 37.3337, -121.8907, 2, 1, 1, '["wifi","kitchen","air_conditioning","workspace","washer"]', 199, 60, 'active', 4.78, 55, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 640 DAY), '/photos/p_007.jpg'),
  ('p_008', 'h_006', 'Naglee Park Guest Suite', 'Private guest suite behind a 1920s home in Naglee Park, with its own entrance, kitchenette and driveway spot.', 'guest_suite', '1021 E San Antonio St', 'San Jose', 'CA', '95116', 37.3405, -121.8707, 2, 1, 1, '["wifi","kitchen","parking","heating"]', 165, 45, 'active', 4.55, 12, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 210 DAY), '/photos/p_008.jpg'),
  ('p_009', 'h_004', 'North San Jose Tech Corridor Townhouse', 'Three-bedroom townhouse near the tech campuses and light rail, with a garage and EV charger.', 'townhouse', '3920 Zanker Rd', 'San Jose', 'CA', '95134', 37.39, -121.93, 5, 3, 2.5, '["wifi","kitchen","parking","washer","dryer","workspace","ev_charger","air_conditioning"]', 260, 90, 'active', 4.68, 37, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 480 DAY), '/photos/p_009.jpg'),
  ('p_010', 'h_007', 'Evergreen Hillside Private Room', 'Private room with its own bathroom in a hillside home with valley views. Shared living room, no kitchen access.', 'private_room', '3305 Silver Creek Rd', 'San Jose', 'CA', '95135', 37.32, -121.774, 2, 1, 1, '["wifi","parking","heating","air_conditioning"]', 89, 25, 'active', 4.81, 15, DATE_SUB(UTC_TIMESTAMP(3), INTERVAL 160 DAY), '/photos/p_010.jpg'),
